@media (prefers-color-scheme: light) {
  :root.skin-theme-clientpref-os,
  .vector-feature-night-mode-enabled,
  .skin-invert,
  .notheme {
    color-scheme: light;
  }
  :root.skin-theme-clientpref-os ::selection,
  .vector-feature-night-mode-enabled ::selection,
  .skin-invert ::selection,
  .notheme ::selection {
    background-color: rgba(136, 57, 239, 0.3);
  }
  :root.skin-theme-clientpref-os input::placeholder,
  .vector-feature-night-mode-enabled input::placeholder,
  .skin-invert input::placeholder,
  .notheme input::placeholder,
  :root.skin-theme-clientpref-os textarea::placeholder,
  .vector-feature-night-mode-enabled textarea::placeholder,
  .skin-invert textarea::placeholder,
  .notheme textarea::placeholder {
    color: #6c6f85 !important;
  }
  :root.skin-theme-clientpref-os #content table,
  .vector-feature-night-mode-enabled #content table,
  .skin-invert #content table,
  .notheme #content table,
  :root.skin-theme-clientpref-os #content h1,
  .vector-feature-night-mode-enabled #content h1,
  .skin-invert #content h1,
  .notheme #content h1,
  :root.skin-theme-clientpref-os #content h2,
  .vector-feature-night-mode-enabled #content h2,
  .skin-invert #content h2,
  .notheme #content h2,
  :root.skin-theme-clientpref-os #content h3,
  .vector-feature-night-mode-enabled #content h3,
  .skin-invert #content h3,
  .notheme #content h3,
  :root.skin-theme-clientpref-os #content h4,
  .vector-feature-night-mode-enabled #content h4,
  .skin-invert #content h4,
  .notheme #content h4,
  :root.skin-theme-clientpref-os #content h5,
  .vector-feature-night-mode-enabled #content h5,
  .skin-invert #content h5,
  .notheme #content h5,
  :root.skin-theme-clientpref-os #content pre,
  .vector-feature-night-mode-enabled #content pre,
  .skin-invert #content pre,
  .notheme #content pre,
  :root.skin-theme-clientpref-os #content code,
  .vector-feature-night-mode-enabled #content code,
  .skin-invert #content code,
  .notheme #content code,
  :root.skin-theme-clientpref-os #content tt,
  .vector-feature-night-mode-enabled #content tt,
  .skin-invert #content tt,
  .notheme #content tt {
    color: #4c4f69 !important;
  }
  :root.skin-theme-clientpref-os body.skin-vector-2022 .vector-sticky-header,
  .vector-feature-night-mode-enabled body.skin-vector-2022 .vector-sticky-header,
  .skin-invert body.skin-vector-2022 .vector-sticky-header,
  .notheme body.skin-vector-2022 .vector-sticky-header {
    color: #4c4f69 !important;
    background-color: #e6e9ef !important;
    border-bottom-color: #1e66f5 !important;
  }
  :root.skin-theme-clientpref-os #vector-main-menu-pinned-container,
  .vector-feature-night-mode-enabled #vector-main-menu-pinned-container,
  .skin-invert #vector-main-menu-pinned-container,
  .notheme #vector-main-menu-pinned-container,
  :root.skin-theme-clientpref-os #vector-page-tools-pinned-container,
  .vector-feature-night-mode-enabled #vector-page-tools-pinned-container,
  .skin-invert #vector-page-tools-pinned-container,
  .notheme #vector-page-tools-pinned-container {
    background-color: #eff1f5 !important;
  }
  :root.skin-theme-clientpref-os #ooui-php-191,
  .vector-feature-night-mode-enabled #ooui-php-191,
  .skin-invert #ooui-php-191,
  .notheme #ooui-php-191,
  :root.skin-theme-clientpref-os #preferences .mw-htmlform-submit-buttons,
  .vector-feature-night-mode-enabled #preferences .mw-htmlform-submit-buttons,
  .skin-invert #preferences .mw-htmlform-submit-buttons,
  .notheme #preferences .mw-htmlform-submit-buttons {
    background-color: #e6e9ef !important;
  }
  :root.skin-theme-clientpref-os .mw-echo-ui-notificationItemWidget-content-message-header,
  .vector-feature-night-mode-enabled .mw-echo-ui-notificationItemWidget-content-message-header,
  .skin-invert .mw-echo-ui-notificationItemWidget-content-message-header,
  .notheme .mw-echo-ui-notificationItemWidget-content-message-header,
  :root.skin-theme-clientpref-os .oo-ui-labelElement-label,
  .vector-feature-night-mode-enabled .oo-ui-labelElement-label,
  .skin-invert .oo-ui-labelElement-label,
  .notheme .oo-ui-labelElement-label {
    color: #4c4f69 !important;
  }
  :root.skin-theme-clientpref-os .oo-ui-optionWidget-selected,
  .vector-feature-night-mode-enabled .oo-ui-optionWidget-selected,
  .skin-invert .oo-ui-optionWidget-selected,
  .notheme .oo-ui-optionWidget-selected {
    background-color: #acb0be !important;
  }
  :root.skin-theme-clientpref-os .oo-ui-buttonElement-framed.oo-ui-widget-disabled > .oo-ui-buttonElement-button,
  .vector-feature-night-mode-enabled .oo-ui-buttonElement-framed.oo-ui-widget-disabled > .oo-ui-buttonElement-button,
  .skin-invert .oo-ui-buttonElement-framed.oo-ui-widget-disabled > .oo-ui-buttonElement-button,
  .notheme .oo-ui-buttonElement-framed.oo-ui-widget-disabled > .oo-ui-buttonElement-button {
    background-color: #ccd0da !important;
    color: #4c4f69 !important;
    border-color: #acb0be !important;
